contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint unlockTime, uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Setup: deposit Ether for the caller.
        c.Put{value: depositAmount}(unlockTime);

        (, uint balanceAfterPut) = c.Acc(msg.sender);
        (, uint unlockAfterPut) = c.Acc(msg.sender);
        uint cBalanceAfterPut = address(c).balance;

        // Read MinSum through its public getter.
        uint minSum = c.MinSum();

        // The deciding call: attempt to collect.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, uint balanceAfterCollect) = c.Acc(msg.sender);
        uint cBalanceAfterCollect = address(c).balance;

        // General rules that must hold for every input:
        // 1. The recorded balance after Put equals the deposited amount (initial balance was zero).
        assert(balanceAfterPut == depositAmount);

        // 2. The unlock time is at least the Put argument and at least the timestamp when Put ran.
        assert(unlockAfterPut >= unlockTime);

        // 3. A Collect can only succeed when balance is at least MinSum, at least the requested amount,
        //    and the unlock time has passed; a failed Collect leaves state unchanged.
        if (!reverted) {
            // Successful Collect: conditions were met.
            assert(balanceAfterPut >= minSum || depositAmount >= minSum);
            assert(depositAmount >= collectAmount);
            // The balance decreases exactly by the collected amount (no underflow).
            assert(balanceAfterCollect + collectAmount == balanceAfterPut);
            // The contract's Ether balance decreases by exactly the collected amount.
            assert(cBalanceAfterCollect + collectAmount == cBalanceAfterPut);
        } else {
            // Reverted Collect: the recorded balance and contract balance are unchanged.
            assert(balanceAfterCollect == balanceAfterPut);
            assert(cBalanceAfterCollect == cBalanceAfterPut);
        }
    }
}

